--> statement-breakpoint
CREATE TRIGGER occupancy_stay_valid_update BEFORE UPDATE ON occupancy_stays WHEN COALESCE((EXISTS(SELECT 1 FROM properties p WHERE p.id=NEW.property_id AND p.owner_id=NEW.owner_id AND p.archived_at IS NULL AND p.state_code IS NEW.state_code AND p.worksite_id IS NEW.worksite_id AND COALESCE((SELECT version FROM occupancy_property_scopes WHERE property_id=p.id),0)=NEW.scope_version) AND typeof(NEW.slot_number)='integer' AND NEW.slot_number BETWEEN 1 AND 200 AND typeof(NEW.revision)='integer' AND NEW.revision>=1 AND typeof(NEW.scope_version)='integer' AND NEW.scope_version>=0 AND (NEW.entry_on IS NULL OR (length(NEW.entry_on)=10 AND NEW.entry_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(NEW.entry_on,'+0 days') IS NEW.entry_on AND NEW.entry_on<=date('now','-3 hours'))) AND (NEW.exit_on IS NULL OR (length(NEW.exit_on)=10 AND NEW.exit_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(NEW.exit_on,'+0 days') IS NEW.exit_on AND NEW.exit_on<=date('now','-3 hours') AND NEW.exit_on>=COALESCE(NEW.entry_on,date(NEW.created_at,'-3 hours')))) AND OLD.exit_on IS NULL AND ((NEW.exit_on IS NOT NULL AND NEW.planned_exit_on IS OLD.planned_exit_on) OR (NEW.exit_on IS NULL AND NEW.planned_exit_on IS NOT OLD.planned_exit_on)) AND NEW.revision=OLD.revision+1 AND NEW.last_event_id<>OLD.last_event_id AND NEW.request_id<>OLD.request_id),0)=0 BEGIN SELECT RAISE(ABORT,'occupancy_stay_invalid'); END;
--> statement-breakpoint
DROP TRIGGER occupancy_stays_event_insert;
--> statement-breakpoint
CREATE TRIGGER occupancy_stays_event_insert AFTER INSERT ON occupancy_stays BEGIN INSERT INTO occupancy_events(id,owner_id,property_id,room_id,stay_id,state_code,worksite_id,scope_version,action,revision,before_snapshot,after_snapshot,actor_user_id,actor_name,request_id,request_fingerprint,created_at) VALUES(NEW.last_event_id,NEW.owner_id,NEW.property_id,NEW.room_id,NEW.id,NEW.state_code,NEW.worksite_id,NEW.scope_version,'check_in',NEW.revision,'null',json_object('id',NEW.id,'property_id',NEW.property_id,'room_id',NEW.room_id,'state_code',NEW.state_code,'worksite_id',NEW.worksite_id,'scope_version',NEW.scope_version,'room_name',NEW.room_name,'slot_number',NEW.slot_number,'person_profile_id',NEW.person_profile_id,'person_name',NEW.person_name,'person_title',NEW.person_title,'shift',NEW.shift,'entry_on',NEW.entry_on,'exit_on',NEW.exit_on,'planned_exit_on',NEW.planned_exit_on,'client_id',NEW.client_id,'client_name',NEW.client_name,'cost_center_id',NEW.cost_center_id,'cost_center_name',NEW.cost_center_name,'assignment_captured_at',NEW.assignment_captured_at,'revision',NEW.revision),NEW.actor_user_id,NEW.actor_name,NEW.request_id,NEW.request_fingerprint,NEW.updated_at); END;
--> statement-breakpoint
DROP TRIGGER occupancy_stays_event_update;
--> statement-breakpoint
CREATE TRIGGER occupancy_stays_event_update AFTER UPDATE ON occupancy_stays BEGIN INSERT INTO occupancy_events(id,owner_id,property_id,room_id,stay_id,state_code,worksite_id,scope_version,action,revision,before_snapshot,after_snapshot,actor_user_id,actor_name,request_id,request_fingerprint,created_at) VALUES(NEW.last_event_id,NEW.owner_id,NEW.property_id,NEW.room_id,NEW.id,NEW.state_code,NEW.worksite_id,NEW.scope_version,CASE WHEN NEW.exit_on IS NULL THEN 'plan_checkout' ELSE 'check_out' END,NEW.revision,json_object('id',OLD.id,'property_id',OLD.property_id,'room_id',OLD.room_id,'state_code',OLD.state_code,'worksite_id',OLD.worksite_id,'scope_version',OLD.scope_version,'room_name',OLD.room_name,'slot_number',OLD.slot_number,'person_profile_id',OLD.person_profile_id,'person_name',OLD.person_name,'person_title',OLD.person_title,'shift',OLD.shift,'entry_on',OLD.entry_on,'exit_on',OLD.exit_on,'planned_exit_on',OLD.planned_exit_on,'client_id',OLD.client_id,'client_name',OLD.client_name,'cost_center_id',OLD.cost_center_id,'cost_center_name',OLD.cost_center_name,'assignment_captured_at',OLD.assignment_captured_at,'revision',OLD.revision),json_object('id',NEW.id,'property_id',NEW.property_id,'room_id',NEW.room_id,'state_code',NEW.state_code,'worksite_id',NEW.worksite_id,'scope_version',NEW.scope_version,'room_name',NEW.room_name,'slot_number',NEW.slot_number,'person_profile_id',NEW.person_profile_id,'person_name',NEW.person_name,'person_title',NEW.person_title,'shift',NEW.shift,'entry_on',NEW.entry_on,'exit_on',NEW.exit_on,'planned_exit_on',NEW.planned_exit_on,'client_id',NEW.client_id,'client_name',NEW.client_name,'cost_center_id',NEW.cost_center_id,'cost_center_name',NEW.cost_center_name,'assignment_captured_at',NEW.assignment_captured_at,'revision',NEW.revision),NEW.actor_user_id,NEW.actor_name,NEW.request_id,NEW.request_fingerprint,NEW.updated_at); END;
--> statement-breakpoint
DROP TRIGGER occupancy_event_valid;
--> statement-breakpoint
CREATE TRIGGER occupancy_event_valid BEFORE INSERT ON occupancy_events WHEN NOT (json_valid(NEW.before_snapshot) AND json_valid(NEW.after_snapshot) AND NEW.action IN('room_create','room_update','check_in','check_out','plan_checkout') AND EXISTS(SELECT 1 FROM properties p WHERE p.id=NEW.property_id AND p.owner_id=NEW.owner_id AND p.archived_at IS NULL AND p.state_code IS NEW.state_code AND p.worksite_id IS NEW.worksite_id AND COALESCE((SELECT version FROM occupancy_property_scopes WHERE property_id=p.id),0)=NEW.scope_version) AND ((NEW.action IN('room_create','room_update') AND NEW.stay_id IS NULL AND EXISTS(SELECT 1 FROM occupancy_rooms r WHERE r.id=NEW.room_id AND r.property_id=NEW.property_id AND r.owner_id=NEW.owner_id AND r.last_event_id=NEW.id AND r.request_id=NEW.request_id AND r.request_fingerprint=NEW.request_fingerprint AND r.revision=NEW.revision AND r.scope_version=NEW.scope_version AND r.state_code IS NEW.state_code AND r.worksite_id IS NEW.worksite_id)) OR (NEW.action IN('check_in','check_out','plan_checkout') AND EXISTS(SELECT 1 FROM occupancy_stays s WHERE s.id=NEW.stay_id AND s.room_id=NEW.room_id AND s.property_id=NEW.property_id AND s.owner_id=NEW.owner_id AND s.last_event_id=NEW.id AND s.request_id=NEW.request_id AND s.request_fingerprint=NEW.request_fingerprint AND s.revision=NEW.revision AND s.scope_version=NEW.scope_version AND s.state_code IS NEW.state_code AND s.worksite_id IS NEW.worksite_id)))) BEGIN SELECT RAISE(ABORT,'occupancy_event_invalid'); END;
--> statement-breakpoint
CREATE TRIGGER occupancy_assignment_immutable BEFORE UPDATE OF client_id,client_name,cost_center_id,cost_center_name,assignment_captured_at ON occupancy_stays BEGIN SELECT RAISE(ABORT,'occupancy_identity_immutable'); END;
--> statement-breakpoint
CREATE TRIGGER occupancy_forecast_valid_insert BEFORE INSERT ON occupancy_stays WHEN NEW.planned_exit_on IS NOT NULL AND NOT (length(NEW.planned_exit_on)=10 AND NEW.planned_exit_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(NEW.planned_exit_on,'+0 days') IS NEW.planned_exit_on AND NEW.planned_exit_on>=COALESCE(NEW.entry_on,date(NEW.created_at,'-3 hours'))) BEGIN SELECT RAISE(ABORT,'occupancy_forecast_invalid'); END;
--> statement-breakpoint
CREATE TRIGGER occupancy_forecast_valid_update BEFORE UPDATE OF planned_exit_on ON occupancy_stays WHEN NEW.planned_exit_on IS NOT NULL AND NOT (length(NEW.planned_exit_on)=10 AND NEW.planned_exit_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(NEW.planned_exit_on,'+0 days') IS NEW.planned_exit_on AND NEW.planned_exit_on>=COALESCE(NEW.entry_on,date(NEW.created_at,'-3 hours'))) BEGIN SELECT RAISE(ABORT,'occupancy_forecast_invalid'); END;
